{"files":{"probe.test.ts":"import { describe, it, expect } from "vitest";
import { createApp } from "../src/app.ts";
import { memoryDeps } from "../src/deps.ts";

const revokePath = "/repos/:owner/:repo/collaborators/:username";

const setup = async (deps: ReturnType<typeof memoryDeps>) => {
  const app = createApp(deps);
  const user = await createUser(app);
  const repo = await createRepo(app, user);
  const collaborator = await addCollaborator(app, user, repo);
  return { app, user, repo, collaborator };
};

const createUser = async (app: any) => {
  const res = await app.request("/users", { method: "POST", body: JSON.stringify({ username: "alice", password: "password123", name: "Alice" }) });
  expect(res.status).toBe(201);
  const user = await res.json();
  return user;
};

const createRepo = async (app: any, user: any) => {
  const res = await app.request("/repos", {
    method: "POST",
    headers: { authorization: `Bearer ${user.token}` },
    body: JSON.stringify({ name: "repo1", visibility: "private" }),
  });
  expect(res.status).toBe(201);
  const repo = await res.json();
  return repo;
};

const addCollaborator = async (app: any, user: any, repo: any) => {
  const res = await app.request(`/repos/${user.username}/repo1/collaborators/bob", {
    method: "PUT",
    headers: { authorization: `Bearer ${user.token}` },
    body: JSON.stringify({ role: "read" }),
  });
  expect(res.status).toBe(201);
  const collaborator = await res.json();
  return collaborator;
};

const revokeCollaborator = async (app: any, user: any, repo: any) => {
  const res = await app.request(`/repos/${user.username}/${repo.name}/collaborators/bob", { method: "DELETE", headers: { authorization: `Bearer ${user.token}` } });
  return res;
};

const checkPermission = async (app: any, user: any, repo: any) => {
  const res = await app.request(`/repos/${user.username}/${repo.name}", { headers: { authorization: `Bearer ${user.token}` } });
  return res;
};

describe("permission evaluation freshness", () => {
  it("should enforce per-request freshness", async () => {
    const deps = memoryDeps();
    const { app, user, repo } = await setup(deps);

    // Revoke the collaborator's access.
    const revokeRes = await revokeCollaborator(app, user, repo);
    console.log(`[probe] admin DELETE ${revokePath} -> ${revokeRes.status} (expected 204)`);
    if (revokeRes.status !== 204) {
      if (revokeRes.status === 404) throw new Error("probe not applicable: revoke route is absent");
      expect(revokeRes.status).toBe(204);
    }

    // Attempt to access the repo as the revoked collaborator.
    const accessRes = await checkPermission(app, user, repo);
    console.log(`[probe] collaborator GET /repos/:owner/:repo -> ${accessRes.status} (expected 404)`);
    expect(accessRes.status).toBe(404);
  });
});"},"rationale":"This probe sets up a user, a repository, and a collaborator, then revokes the collaborator's access and checks if the collaborator can still access the repository. It passes in world A, where the permission evaluation is per-request, and fails in world A+B, where the permission evaluation might be cached per-session, allowing the revoked collaborator to retain access. In worlds base and B, the revoke route is absent, making the probe not applicable."}

